import test from "node:test";
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import assert from "node:assert/strict";
import * as fs from "node:fs/promises";
import * as os from "node:os";
import * as path from "node:path";
import { getAgentDiscoverySnapshot } from "../src/agents.ts";
import { acceptConfigRevisionInternal, admitDispatchCallInternal, admitNextChainStepInternal, bindChildSessionInternal as bindChildSessionInternalBase, claimExecutionOwnerInternal as claimExecutionOwnerInternalBase, executeDelegationInternal as executeDelegationInternalBase, executeReattachedDelegationInternal as executeReattachedDelegationInternalBase, finalizeCallInternal, markDelegationReturnedInternal as markDelegationReturnedInternalBase, markSpawnStartedInternal as markSpawnStartedInternalBase, normalizeExecutionStartupInternal, normalizeStartupInternal, readDelegationInternal, readDispatchCallInternal, reconcilePrivateOrphans, resolveDelegationInternal, reserveInitialInternal as reserveInitialInternalBase, reserveRecoveryCycleInternal as reserveRecoveryCycleInternalBase, delegationFoundationCapability } from "../src/delegation-internal.ts";
import type { ChildIdentity, ConfigRevisionActor, DelegationFoundationDependencies, DispatchCallAdmissionRequest, OwnerClaim, OwnerIdentity, ProjectTrustBinding } from "../src/delegation.ts";
import { ActiveLineageTracker, lineageMatches, type ActiveLineage } from "../src/lineage.ts";
import { resolveAgent, resolveAgentWithAudit } from "../src/resolver.ts";

const parentSessionId = "parent-1";
async function root(): Promise<string> { return fs.mkdtemp(path.join(os.tmpdir(), "subagent-v2-review-")); }
function inProcessLineage(): ActiveLineage { return { parentSessionId, activeLineageId: "lineage-1", activeBranchAnchor: "leaf-1", currentLeafId: "leaf-1", branchIds: ["root", "leaf-1"], persistence: "in_process_only" }; }
function request(overrides: Partial<DispatchCallAdmissionRequest> = {}): DispatchCallAdmissionRequest {
  return { parentSessionId, lineage: inProcessLineage(), toolCallId: "tool-call-opaque", cwd: "/tmp/project", mode: "single", single: { agent: "implement", task: "secret task", cwd: "/tmp/project" }, agentScope: "user", ...overrides };
}
async function projectAgents(dir: string, files: Record<string, string>): Promise<void> {
  await fs.mkdir(dir, { recursive: true, mode: 0o755 }); await fs.chmod(dir, 0o755);
  for (const [name, content] of Object.entries(files)) { await fs.writeFile(path.join(dir, name), content, { mode: 0o644 }); await fs.chmod(path.join(dir, name), 0o644); }
}
const definition = (name: string, aliases = "") => `---\nname: ${name}\ndescription: ${name}\naliases: [${aliases}]\n---\nInstructions`;
async function trust(rootDir: string): Promise<ProjectTrustBinding> { const snapshot = getAgentDiscoverySnapshot(rootDir); assert.ok(snapshot); return { parentSessionId, discoveryRootRealpath: snapshot.rootRealpath, snapshotDigest: snapshot.digest }; }
const executionDeps = (deps: DelegationFoundationDependencies = {}) => ({ ...deps, lineage: deps.lineage ?? inProcessLineage() });
const reserveInitialInternal = (rootDir: string, callId: string, delegationId: string, deps: DelegationFoundationDependencies = {}) => reserveInitialInternalBase(rootDir, callId, delegationId, executionDeps(deps));
const reserveRecoveryCycleInternal = (rootDir: string, callId: string, delegationId: string, deps: DelegationFoundationDependencies = {}) => reserveRecoveryCycleInternalBase(rootDir, callId, delegationId, executionDeps(deps));
const claimExecutionOwnerInternal = (rootDir: string, callId: string, delegationId: string, owner: OwnerIdentity, deps: DelegationFoundationDependencies = {}) => claimExecutionOwnerInternalBase(rootDir, callId, delegationId, owner, executionDeps(deps));
const markSpawnStartedInternal = (rootDir: string, callId: string, delegationId: string, kind: "initial" | "recovery", deps: DelegationFoundationDependencies = {}) => markSpawnStartedInternalBase(rootDir, callId, delegationId, kind, executionDeps(deps));
const bindChildSessionInternal = (rootDir: string, callId: string, delegationId: string, claim: OwnerClaim, childSessionId: string, sessionPath?: string, pid?: number, deps: DelegationFoundationDependencies = {}, attempt?: number) => bindChildSessionInternalBase(rootDir, callId, delegationId, claim, childSessionId, sessionPath, pid, executionDeps(deps), attempt);
const markDelegationReturnedInternal = (rootDir: string, callId: string, delegationId: string, outcome: "success" | "failure" | "cancelled", resultRef: string, claim: OwnerClaim, deps: DelegationFoundationDependencies = {}) => markDelegationReturnedInternalBase(rootDir, callId, delegationId, outcome, resultRef, claim, executionDeps(deps));
const executeDelegationInternal = (rootDir: string, callId: string, delegationId: string, agent: any, deps: any = {}) => executeDelegationInternalBase(rootDir, callId, delegationId, agent, executionDeps(deps));
const executeReattachedDelegationInternal = (rootDir: string, callId: string, delegationId: string, executor: any, deps: any = {}) => executeReattachedDelegationInternalBase(rootDir, callId, delegationId, executor, executionDeps(deps));
const reconcileRunningChildInternal = (rootDir: string, callId: string, delegationId: string, inspect: any, deps: DelegationFoundationDependencies = {}) => reconcileRunningChildInternalBase(rootDir, callId, delegationId, inspect, executionDeps(deps));
async function readWal(rootDir: string, callId: string): Promise<any[]> { return (await fs.readFile(path.join(rootDir, "v2", "wal", `${callId}.jsonl`), "utf8")).trim().split("\n").map((line) => JSON.parse(line)); }
async function appendWalForTest(rootDir: string, callId: string, type: string, data: Record<string, unknown>, delegationId: string): Promise<void> { const file = path.join(rootDir, "v2", "wal", `${callId}.jsonl`); const events = await readWal(rootDir, callId); const previous = events.at(-1)!; const body = { version: 1, seq: previous.seq + 1, type, callId, delegationId, data, prevChecksum: previous.checksum }; const event = { ...body, checksum: createHash("sha256").update(JSON.stringify(body)).digest("hex") }; await fs.appendFile(file, `${JSON.stringify(event)}\n`); }
async function exists(file: string): Promise<boolean> { return fs.stat(file).then(() => true).catch(() => false); }
async function privateSnapshot(rootDir: string): Promise<Record<string, string>> { const result: Record<string, string> = {}; for (const file of (await fs.readdir(path.join(rootDir, "v2", "private"))).sort()) result[file] = await fs.readFile(path.join(rootDir, "v2", "private", file), "utf8"); return result; }
function revisionActor(actorId = "test-actor"): ConfigRevisionActor { return { actorId, parentSessionId, activeLineageId: inProcessLineage().activeLineageId, activeBranchAnchor: inProcessLineage().activeBranchAnchor }; }
function claimFrom(started: { owner?: OwnerIdentity; ownerGeneration?: number; fencingGeneration?: number; spawnId?: string }): OwnerClaim { return { owner: started.owner!, ownerGeneration: started.ownerGeneration!, fencingGeneration: started.fencingGeneration!, spawnId: started.spawnId! }; }
function staleClaim(spawnId = "stale-spawn", fencingGeneration = 0, ownerGeneration = 1): OwnerClaim { return { owner: { host: os.hostname(), pid: process.pid, birth: "stale-claim", parentSessionId, parentSessionPath: "/tmp/parent", argvProof: "0".repeat(64) }, ownerGeneration, fencingGeneration, spawnId }; }
function acceptRevisionForTest(rootDir: string, dispatchCallId: string, delegationId: string, projectTrust: ProjectTrustBinding | undefined, actor: ConfigRevisionActor, deps?: DelegationFoundationDependencies) { return acceptConfigRevisionInternal(rootDir, dispatchCallId, delegationId, projectTrust, actor, deps); }

function projectRequest(projectRoot: string, projectTrust: ProjectTrustBinding, overrides: Partial<DispatchCallAdmissionRequest> = {}): DispatchCallAdmissionRequest {
  return request({ cwd: "/tmp/not-the-project-root", agentScope: "project", projectTrust, single: { agent: "implement", task: "private task", cwd: "/tmp/not-the-project-root" }, ...overrides });
}

async function admitProject(rootDir: string, projectRoot: string, toolCallId = "project-call") {
  const projectTrust = await trust(projectRoot);
  return { projectTrust, result: await admitDispatchCallInternal(projectRequest(projectRoot, projectTrust, { toolCallId }), rootDir) };
}

test("strict shape and idempotent admission repair all required slots in reference-before-admitted order", async (t) => {
  const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true }));
  const invalid = await admitDispatchCallInternal(request({ mode: "parallel", single: undefined, tasks: [], chain: [] } as any), rootDir);
  assert.equal(invalid.state, "invalid"); assert.equal(await exists(path.join(rootDir, "v2")), false);
  const parallelRequest = request({ mode: "parallel", single: undefined, tasks: [{ agent: "a", task: "one" }, { agent: "a", task: "two" }], toolCallId: "parallel" });
  let fail = true;
  await assert.rejects(() => admitDispatchCallInternal(parallelRequest, rootDir, { fault: (point) => { if (fail && point === "after:delegation_admitted") { fail = false; throw new Error("kill-after-admitted"); } } }));
  const repaired = await admitDispatchCallInternal(parallelRequest, rootDir);
  assert.equal(repaired.state, "admitted"); assert.equal(repaired.delegationIds?.length, 2);
  const events = await readWal(rootDir, repaired.dispatchCallId!);
  const refs = events.filter((event) => event.type === "call_delegation_reference_added"); const admissions = events.filter((event) => event.type === "delegation_admitted");
  assert.equal(refs.length, 2); assert.equal(admissions.length, 2); assert.ok(refs.every((ref) => admissions.some((admission) => admission.delegationId === ref.delegationId && ref.seq < admission.seq && ref.data.required === true)));
  assert.equal(await exists(path.join(rootDir, "v2", "proofs", `${repaired.dispatchCallId}.json`)), false); const conflict = await admitDispatchCallInternal({ ...parallelRequest, tasks: [{ agent: "a", task: "changed" }, { agent: "a", task: "two" }] }, rootDir); assert.equal(conflict.state, "rejected");
  const wal = await fs.readFile(path.join(rootDir, "v2", "wal", `${repaired.dispatchCallId}.jsonl`), "utf8"); assert.equal(wal.includes("secret task"), false); assert.equal(wal.includes("/tmp/project"), false);
});

test("private call payload digest is recomputed and cross-checked on every read", async (t) => { const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const req = request({ toolCallId: "payload-digest" }); const admitted = await admitDispatchCallInternal(req, rootDir); const file = path.join(rootDir, "v2", "private", `call-${admitted.dispatchCallId}.json`); const payload = JSON.parse(await fs.readFile(file, "utf8")); payload.items[0].task = "tampered"; await fs.writeFile(file, JSON.stringify(payload), { mode: 0o600 }); assert.equal((await admitDispatchCallInternal(req, rootDir)).state, "paused_integrity"); });

test("private payload IDs are deterministic and orphan reconciler removes payloads before call WAL", async (t) => {
  const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const req = request({ toolCallId: "before-call-wal" }); await assert.rejects(() => admitDispatchCallInternal(req, rootDir, { fault: (point) => { if (point === "before:call_admitted") throw new Error("kill-before-call-wal"); } })); await reconcilePrivateOrphans(rootDir); assert.deepEqual(await fs.readdir(path.join(rootDir, "v2", "private")), []); const retry = await admitDispatchCallInternal(req, rootDir); assert.equal(retry.state, "admitted"); const files = await fs.readdir(path.join(rootDir, "v2", "private")); assert.ok(files.some((file) => file.startsWith("call-"))); assert.ok(files.some((file) => /^[0-9a-f]{64}\.json$/.test(file)));
});

test("missing reference is never accepted or materialized; retry converges after reference kill point", async (t) => {
  const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); let killed = false;
  const req = request({ toolCallId: "reference-kill" });
  await assert.rejects(() => admitDispatchCallInternal(req, rootDir, { fault: (point) => { if (!killed && point === "after:call_delegation_reference_added") { killed = true; throw new Error("kill-after-reference"); } } }));
  const [partialWal] = await fs.readdir(path.join(rootDir, "v2", "wal")); const partial = await readDispatchCallInternal(rootDir, partialWal.slice(0, -6)); assert.equal(partial?.state, "repair_required");
  const retry = await admitDispatchCallInternal(req, rootDir); assert.equal(retry.state, "admitted");
  assert.equal(await exists(path.join(rootDir, "v2", "proofs", `${retry.dispatchCallId}.json`)), false);
  const view = await readDispatchCallInternal(rootDir, retry.dispatchCallId!); assert.equal(view?.state, "admitted");
});

test("chain cannot admit next step before durable returned, then advances cursor after admission", async (t) => {
  const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "agents"); await projectAgents(project, { "agent.md": definition("implement") }); const projectTrust = await trust(project);
  const req = projectRequest(project, projectTrust, { mode: "chain", toolCallId: "chain", chain: [{ agent: "implement", task: "one" }, { agent: "implement", task: "two" }], single: undefined });
  const admitted = await admitDispatchCallInternal(req, rootDir); assert.equal(admitted.state, "admitted"); assert.ok(admitted.view?.slots.every((slot) => slot.required)); const first = admitted.delegationIds![0];
  const early = await admitNextChainStepInternal(rootDir, admitted.dispatchCallId!, inProcessLineage()); assert.equal(early.state, "rejected");
  assert.equal((await readDispatchCallInternal(rootDir, admitted.dispatchCallId!))?.chainCursor, 0);
  assert.equal((await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, first)).state, "resolved"); assert.equal((await reserveInitialInternal(rootDir, admitted.dispatchCallId!, first)).state, "reserved"); const firstStarted = await markSpawnStartedInternal(rootDir, admitted.dispatchCallId!, first, "initial"); assert.equal(firstStarted.state, "initial_running"); assert.equal((await markDelegationReturnedInternal(rootDir, admitted.dispatchCallId!, first, "success", "result:first", claimFrom(firstStarted))).state, "returned");
  const next = await admitNextChainStepInternal(rootDir, admitted.dispatchCallId!, inProcessLineage()); assert.equal(next.state, "admitted"); assert.equal(next.slotIndex, 1); assert.equal((await readDispatchCallInternal(rootDir, admitted.dispatchCallId!))?.chainCursor, 1);
  const killRoot = await root(); t.after(() => fs.rm(killRoot, { recursive: true, force: true })); const killReq = projectRequest(project, projectTrust, { mode: "chain", toolCallId: "chain-kill", chain: [{ agent: "implement", task: "one" }, { agent: "implement", task: "two" }], single: undefined }); const killCall = await admitDispatchCallInternal(killReq, killRoot); const killFirst = killCall.delegationIds![0]; await resolveDelegationInternal(killRoot, killCall.dispatchCallId!, killFirst); await reserveInitialInternal(killRoot, killCall.dispatchCallId!, killFirst); const killStarted = await markSpawnStartedInternal(killRoot, killCall.dispatchCallId!, killFirst, "initial"); await markDelegationReturnedInternal(killRoot, killCall.dispatchCallId!, killFirst, "success", "result:first", claimFrom(killStarted)); await assert.rejects(() => admitNextChainStepInternal(killRoot, killCall.dispatchCallId!, inProcessLineage(), { fault: (point) => { if (point === "after:delegation_admitted") throw new Error("kill-after-next-admitted"); } })); assert.equal((await readDispatchCallInternal(killRoot, killCall.dispatchCallId!))?.state, "repair_required"); assert.equal((await admitNextChainStepInternal(killRoot, killCall.dispatchCallId!, inProcessLineage())).state, "admitted"); assert.equal((await readDispatchCallInternal(killRoot, killCall.dispatchCallId!))?.chainCursor, 1);
});

test("project trust is parent-bound and snapshot-bound; item cwd cannot authorize another root", async (t) => {
  const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "project"); const other = path.join(rootDir, "other"); await projectAgents(project, { "agent.md": definition("implement") }); await projectAgents(other, { "other.md": definition("other") });
  const projectTrust = await trust(project); const req = projectRequest(project, projectTrust, { single: { agent: "implement", task: "x", cwd: other }, cwd: other }); const admitted = await admitDispatchCallInternal(req, rootDir); assert.equal(admitted.state, "admitted");
  assert.equal((await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, admitted.delegationIds![0])).state, "resolved");
  const tampered = { ...projectTrust, snapshotDigest: "0".repeat(64) }; const rejected = await admitDispatchCallInternal(projectRequest(project, tampered, { toolCallId: "bad-snapshot" }), rootDir); assert.equal(rejected.state, "invalid");
  const escaped = resolveAgent(other, "project", "implement", { projectRoot: project, projectTrusted: true, projectSnapshotDigest: projectTrust.snapshotDigest }); assert.equal(escaped.state, "resolved"); const user = path.join(rootDir, "user"); await projectAgents(user, { "user.md": definition("implement", "impl") }); const auditResolution = resolveAgentWithAudit(other, "both", "implement", { userRoot: user, projectRoot: project, projectTrusted: true, projectSnapshotDigest: projectTrust.snapshotDigest }); assert.equal(auditResolution.state, "resolved"); assert.ok(auditResolution.audit.candidates.some((candidate) => candidate.status === "shadowed")); assert.equal(auditResolution.audit.winner?.provenance?.source, "project"); await fs.writeFile(path.join(user, "bad.md"), "not frontmatter", { mode: 0o644 }); await fs.chmod(path.join(user, "bad.md"), 0o644); const invalidAudit = resolveAgentWithAudit(other, "both", "implement", { userRoot: user, projectRoot: project, projectTrusted: true, projectSnapshotDigest: projectTrust.snapshotDigest }); assert.equal(invalidAudit.state, "paused_configuration"); assert.ok(invalidAudit.audit.candidates.some((candidate) => candidate.status === "invalid" && candidate.declaredPath.endsWith("bad.md") && candidate.invalidReason)); await fs.appendFile(path.join(project, "agent.md"), "changed"); const staleSnapshot = resolveAgentWithAudit(other, "project", "implement", { projectRoot: project, projectTrusted: true, projectSnapshotDigest: projectTrust.snapshotDigest }); assert.equal(staleSnapshot.state, "paused_configuration"); assert.ok(staleSnapshot.audit.candidates.some((candidate) => candidate.status === "invalid" && candidate.provenance?.digest));
});

test("canonical provenance is private and public projection contains only hashes", async (t) => {
  const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "project"); await projectAgents(project, { "agent.md": definition("implement", "impl") }); const projectTrust = await trust(project); const admitted = await admitDispatchCallInternal(projectRequest(project, projectTrust), rootDir); const id = admitted.delegationIds![0]; assert.equal((await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id)).state, "resolved");
  const publicDelegation = await readDelegationInternal(rootDir, admitted.dispatchCallId!, id); assert.ok(publicDelegation); assert.equal(JSON.stringify(publicDelegation).includes(project), false); assert.equal(JSON.stringify(publicDelegation).includes("fileRealpath"), false);
  const files = await fs.readdir(path.join(rootDir, "v2", "private")); const binding = files.find((file) => file.startsWith(`binding-${id}`)); assert.ok(binding); const privateBinding = await fs.readFile(path.join(rootDir, "v2", "private", binding!), "utf8"); assert.ok(privateBinding.includes(project)); assert.ok(privateBinding.includes("digest")); const audit = await fs.readFile(path.join(rootDir, "v2", "private", `audit-${id}.json`), "utf8"); assert.ok(audit.includes("candidates")); assert.ok(audit.includes("fileRealpath"));
  await fs.writeFile(path.join(project, "agent.md"), definition("implement", "impl") + "revision\n", { mode: 0o600 }); const revisedTrust = await trust(project); const revised = await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, revisedTrust, revisionActor()); assert.equal(revised.state, "accepted", JSON.stringify(revised)); const publishedBeforeRetry = (await readWal(rootDir, admitted.dispatchCallId!)).filter((event) => event.type === "config_revision_published").length; const privateBeforeRetry = await privateSnapshot(rootDir); const retryRevision = await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, revisedTrust, revisionActor()); assert.equal(retryRevision.state, "accepted", JSON.stringify(retryRevision)); assert.equal((await readWal(rootDir, admitted.dispatchCallId!)).filter((event) => event.type === "config_revision_published").length, publishedBeforeRetry); assert.deepEqual(await privateSnapshot(rootDir), privateBeforeRetry); await fs.writeFile(path.join(project, "agent.md"), definition("implement") + "revision2\n", { mode: 0o644 }); await fs.chmod(path.join(project, "agent.md"), 0o644); const revisedTrust2 = await trust(project); const secondRevision = await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, revisedTrust2, revisionActor()); assert.equal(secondRevision.state, "accepted", JSON.stringify(secondRevision)); const revisionEvents = await readWal(rootDir, admitted.dispatchCallId!); assert.deepEqual(revisionEvents.filter((event) => event.type === "config_revision_accepted").map((event) => event.data.revisionEpoch), [1, 2]); assert.deepEqual(revisionEvents.filter((event) => event.type === "config_revision_published").map((event) => event.data.revisionEpoch), [1, 2]);
  const other = path.join(rootDir, "other"); await projectAgents(other, { "agent.md": definition("implement", "impl") }); const otherTrust = await trust(other); const rebound = await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, otherTrust, revisionActor()); assert.equal(rebound.state, "rejected");
});

test("unchanged config digest is rejected without accepted revision WAL", async (t) => { const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "agents"); await projectAgents(project, { "agent.md": definition("implement") }); const projectTrust = await trust(project); const admitted = await admitDispatchCallInternal(projectRequest(project, projectTrust, { toolCallId: "unchanged-revision" }), rootDir); const id = admitted.delegationIds![0]; await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id); const before = await readWal(rootDir, admitted.dispatchCallId!); assert.equal((await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, projectTrust, revisionActor())).state, "rejected"); const after = await readWal(rootDir, admitted.dispatchCallId!); assert.deepEqual(after, before); assert.equal(after.filter((event) => event.type === "config_revision_accepted").length, 0); });

test("missing revision actor is rejected and test deps cannot substitute for actor", async (t) => { const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "missing-actor-agents"); await projectAgents(project, { "agent.md": definition("implement") }); const projectTrust = await trust(project); const admitted = await admitDispatchCallInternal(projectRequest(project, projectTrust, { toolCallId: "missing-actor" }), rootDir); const id = admitted.delegationIds![0]; await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id); await fs.writeFile(path.join(project, "agent.md"), definition("implement") + "revision\n", { mode: 0o644 }); await fs.chmod(path.join(project, "agent.md"), 0o644); const revisedTrust = await trust(project); const result = await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, revisedTrust, undefined as any, { fault: () => { throw new Error("deps must not substitute actor"); } }); assert.deepEqual(result, { state: "rejected", reason: "revision actor is required" }); assert.equal((await readWal(rootDir, admitted.dispatchCallId!)).some((event) => event.type === "delegation_paused"), false); });

test("config revision pauses durably and converges across WAL kill points", async (t) => { for (const point of ["before:delegation_paused", "after:delegation_paused", "before:config_revision_accepted", "after:config_revision_accepted"]) { const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, `agents-${point.replaceAll(":", "-")}`); await projectAgents(project, { "agent.md": definition("implement") }); const initialTrust = await trust(project); const admitted = await admitDispatchCallInternal(projectRequest(project, initialTrust, { toolCallId: `revision-${point}`, single: { agent: "implement", task: "revision task", cwd: "/tmp/not-the-project-root" } }), rootDir); const id = admitted.delegationIds![0]; assert.equal((await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id)).state, "resolved"); await fs.writeFile(path.join(project, "agent.md"), definition("implement") + "revision\n", { mode: 0o644 }); await fs.chmod(path.join(project, "agent.md"), 0o644); const revisedTrust = await trust(project); let killed = true; await assert.rejects(() => acceptRevisionForTest(rootDir, admitted.dispatchCallId!, id, revisedTrust, revisionActor(), { fault: (name) => { if (killed && name === point) { killed = false; throw new Error(`kill-${point}`); } } })); const afterKill = await readWal(rootDir, admitted.dispatchCallId!); if (point === "before:delegation_paused") assert.equal(afterKill.filter((event) => event.type === "delegation_paused").length, 0); if (point === "before:config_revision_accepted" || point === "after:delegation_paused") assert.equal(afterKill.filter((event) => event.type === "config_revision_accepted").length, 0); if (point === "after:config_revision_accepted") { const bindingFile = path.join(rootDir, "v2", "private", `binding-${id}.json`); const walFile = path.join(rootDir, "v2", "wal", `${admitted.dispatchCallId}.jsonl`); const beforeSibling = await fs.readFile(bindingFile, "utf8"); const walBeforeSibling = await fs.readFile(walFile, "utf8"); const privateBefore = await privateSnapshot(rootDir); const sibling = { ...inProcessLineage(), activeLineageId: "sibling-lineage", activeBranchAnchor: "sibling-leaf", currentLeafId: "sibling-leaf", branchIds: ["root", "sibling-leaf"] }; const siblingStartup = await normalizeStartupInternal(rootDir, sibling); assert.equal(siblingStartup.normalized, 0); assert.equal(await fs.readFile(bindingFile, "utf8"), beforeSibling); assert.equal(await fs.readFile(walFile, "utf8"), walBeforeSibling); const privateAfter = await privateSnapshot(rootDir); assert.deepEqual(privateAfter, privateBefore); const startup = await normalizeStartupInternal(rootDir, inProcessLineage()); assert.equal(startup.pausedIntegrity, 0); assert.equal((await reserveInitialInternal(rootDir, admitted.dispatchCallId!, id)).state, "reserved"); } const retry = await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, revisedTrust, revisionActor()); assert.equal(retry.state, "accepted"); const finalEvents = await readWal(rootDir, admitted.dispatchCallId!); assert.equal(finalEvents.filter((event) => event.type === "config_revision_accepted").length, 1); assert.ok(finalEvents.some((event) => event.type === "delegation_paused")); } });

test("accepted but unpublished revision rejects an injected next epoch", async (t) => { const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "unpublished-epoch-agents"); await projectAgents(project, { "agent.md": definition("implement") }); const admitted = await admitDispatchCallInternal(projectRequest(project, await trust(project), { toolCallId: "unpublished-epoch" }), rootDir); const id = admitted.delegationIds![0]; await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id); await fs.writeFile(path.join(project, "agent.md"), definition("implement") + "epoch1\n", { mode: 0o644 }); await fs.chmod(path.join(project, "agent.md"), 0o644); const revisedTrust = await trust(project); let killed = true; await assert.rejects(() => acceptRevisionForTest(rootDir, admitted.dispatchCallId!, id, revisedTrust, revisionActor("unpublished"), { fault: (point) => { if (killed && point === "after:config_revision_accepted") { killed = false; throw new Error("kill-after-accepted"); } } })); const accepted = (await readWal(rootDir, admitted.dispatchCallId!)).find((event) => event.type === "config_revision_accepted"); assert.ok(accepted); assert.equal((await readWal(rootDir, admitted.dispatchCallId!)).filter((event) => event.type === "config_revision_published").length, 0); await appendWalForTest(rootDir, admitted.dispatchCallId!, "delegation_configuration_observed", { reason: "configuration_observed", revisionId: `${id}:r2`, revisionEpoch: 2, oldDigest: accepted!.data.newDigest, newDigest: "c".repeat(64) }, id); assert.equal((await readDispatchCallInternal(rootDir, admitted.dispatchCallId!))?.state, "paused_integrity"); });

