test("durable revision intent fences actors until publish, then permits the next epoch actor", async (t) => { const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "epoch-agents"); await projectAgents(project, { "agent.md": definition("implement") }); const initialTrust = await trust(project); const admitted = await admitDispatchCallInternal(projectRequest(project, initialTrust, { toolCallId: "epoch-intent" }), rootDir); const id = admitted.delegationIds![0]; await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id); const actorA = { actorId: "actor-a", parentSessionId, activeLineageId: inProcessLineage().activeLineageId, activeBranchAnchor: inProcessLineage().activeBranchAnchor }; const actorB = { ...actorA, actorId: "actor-b" }; await fs.writeFile(path.join(project, "agent.md"), definition("implement") + "epoch1\n", { mode: 0o644 }); await fs.chmod(path.join(project, "agent.md"), 0o644); const trust1 = await trust(project); let killed = true; await assert.rejects(() => acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, trust1, actorA, { fault: (name) => { if (killed && name === "after:delegation_paused") { killed = false; throw new Error("kill-after-pause"); } } })); const intentEvents = await readWal(rootDir, admitted.dispatchCallId!); const intent = intentEvents.find((event) => event.type === "delegation_paused" && event.data.reason === "configuration revision pending"); assert.ok(intent); assert.equal(intent!.data.revisionId, `${id}:r1`); assert.equal(intent!.data.revisionEpoch, 1); assert.match(String(intent!.data.oldDigest), /^[0-9a-f]{64}$/); assert.match(String(intent!.data.newDigest), /^[0-9a-f]{64}$/); assert.equal(intent!.data.actorId, "actor-a"); assert.equal(intent!.data.parentSessionId, parentSessionId); assert.equal(intent!.data.activeLineageId, actorA.activeLineageId); assert.equal(intent!.data.activeBranchAnchor, actorA.activeBranchAnchor); assert.equal((await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, trust1, actorB)).state, "rejected"); assert.equal((await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, trust1, actorA)).state, "accepted"); await fs.writeFile(path.join(project, "agent.md"), definition("implement") + "epoch2\n", { mode: 0o644 }); await fs.chmod(path.join(project, "agent.md"), 0o644); const trust2 = await trust(project); assert.equal((await acceptConfigRevisionInternal(rootDir, admitted.dispatchCallId!, id, trust2, actorB)).state, "accepted"); const accepted = (await readWal(rootDir, admitted.dispatchCallId!)).filter((event) => event.type === "config_revision_accepted"); assert.deepEqual(accepted.map((event) => [event.data.revisionEpoch, event.data.actorId]), [[1, "actor-a"], [2, "actor-b"]]); });

