test("lineage is deterministic across tracker restart, linear append-stable, and fork-specific", async () => {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), "lineage-review-")); const session = path.join(dir, "session.jsonl"); await fs.writeFile(session, "session", { mode: 0o600 }); await fs.chmod(session, 0o600); const entries = [{ id: "root" }, { id: "a", parentId: "root" }, { id: "b", parentId: "a" }, { id: "c", parentId: "a" }, { id: "d", parentId: "b" }]; const manager = (branch: string[]) => ({ getSessionId: () => parentSessionId, getSessionFile: () => session, getLeafId: () => branch.at(-1), getBranch: () => branch.map((id) => entries.find((entry) => entry.id === id)), getEntries: () => entries });
  const first = new ActiveLineageTracker().capture(manager(["root", "a", "b", "d"])); const restart = new ActiveLineageTracker().capture(manager(["root", "a", "b", "d"])); const linear = new ActiveLineageTracker().capture(manager(["root", "a", "b", "d"])); const fork = new ActiveLineageTracker().capture(manager(["root", "a", "c"])); assert.equal(first.persistence, "restart-durable"); assert.equal(first.activeLineageId, restart.activeLineageId); assert.equal(first.activeLineageId, linear.activeLineageId); assert.notEqual(first.activeLineageId, fork.activeLineageId); assert.equal(lineageMatches(first, fork), false); await fs.rm(dir, { recursive: true, force: true });
});

test("lineage keeps an existing persisted branch after a later sibling appears", async (t) => { const dir = await fs.mkdtemp(path.join(os.tmpdir(), "lineage-late-sibling-")); t.after(() => fs.rm(dir, { recursive: true, force: true })); const session = path.join(dir, "session.jsonl"); await fs.writeFile(session, "session", { mode: 0o600 }); const entries: Array<{ id: string; parentId?: string }> = [{ id: "root" }, { id: "a", parentId: "root" }, { id: "b", parentId: "a" }]; const manager = (branch: string[]) => ({ getSessionId: () => parentSessionId, getSessionFile: () => session, getLeafId: () => branch.at(-1), getBranch: () => branch.map((id) => entries.find((entry) => entry.id === id)), getEntries: () => entries }); const before = new ActiveLineageTracker().capture(manager(["root", "a", "b"])); entries.push({ id: "c", parentId: "a" }); const after = new ActiveLineageTracker().capture(manager(["root", "a", "b"])); const sibling = new ActiveLineageTracker().capture(manager(["root", "a", "c"])); assert.equal(before.activeLineageId, after.activeLineageId); assert.notEqual(after.activeLineageId, sibling.activeLineageId); });

test("lineage without complete durable proof downgrades instead of pretending restart durability", () => { const tracker = new ActiveLineageTracker(); const value = tracker.capture({ getSessionId: () => parentSessionId, getLeafId: () => "leaf", getBranch: () => [{ id: "leaf" }] }); assert.equal(value.persistence, "in_process_only"); assert.equal(value.activeLineageId, tracker.capture({ getSessionId: () => parentSessionId, getLeafId: () => "leaf", getBranch: () => [{ id: "leaf" }] }).activeLineageId); });

test("owner claim is exclusive across a real child process and transfer needs two death observations", async (t) => {
  const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "owner-process-agents"); await projectAgents(project, { "target.md": definition("implement"), "conflict.md": definition("other", "implement") }); const admitted = await admitDispatchCallInternal(projectRequest(project, await trust(project), { toolCallId: "owner-process" }), rootDir); const id = admitted.delegationIds![0]; assert.equal((await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id)).state, "paused_configuration");
  const source = path.resolve("packages/subagent/src/delegation-internal.ts"); const code = `import { createHash } from "node:crypto"; import * as os from "node:os"; const m = await import(${JSON.stringify(source)}); const owner = { host: os.hostname(), pid: process.pid, birth: "child-birth", parentSessionId: "parent-1", parentSessionPath: "/tmp/parent-session", argvProof: createHash("sha256").update(JSON.stringify(process.argv)).digest("hex") }; const lineage = { parentSessionId: "parent-1", activeLineageId: "lineage-1", activeBranchAnchor: "leaf-1", currentLeafId: "leaf-1", branchIds: ["root", "leaf-1"], persistence: "in_process_only" }; const result = await m.claimExecutionOwnerInternal(process.env.ROOT, process.env.CALL, process.env.DELEGATION, owner, { lineage }); console.log(JSON.stringify(result)); setInterval(() => {}, 10000);`;
  const child = spawn(process.execPath, ["--experimental-strip-types", "--input-type=module", "-e", code], { env: { ...process.env, ROOT: rootDir, CALL: admitted.dispatchCallId!, DELEGATION: id }, stdio: ["ignore", "pipe", "pipe"] }); t.after(() => { if (!child.killed) child.kill("SIGTERM"); }); const output = await new Promise<string>((resolve, reject) => { let text = ""; child.stdout.on("data", (chunk) => { text += String(chunk); if (text.includes("\n")) resolve(text); }); child.once("error", reject); }); assert.equal(JSON.parse(output.trim()).state, "claimed");
  const parentOwner: OwnerIdentity = { host: os.hostname(), pid: process.pid, birth: "parent-birth", parentSessionId, parentSessionPath: "/tmp/parent-session", argvProof: createHash("sha256").update("parent").digest("hex") }; const busy = await claimExecutionOwnerInternal(rootDir, admitted.dispatchCallId!, id, parentOwner); assert.equal(busy.state, "rejected"); child.kill("SIGTERM"); await new Promise<void>((resolve) => child.once("exit", () => resolve())); const transferred = await claimExecutionOwnerInternal(rootDir, admitted.dispatchCallId!, id, parentOwner); assert.equal(transferred.state, "transferred"); assert.equal((await readDelegationInternal(rootDir, admitted.dispatchCallId!, id))?.state, "paused_configuration");
});

test("terminal completion from an old owner is fenced after transfer", async (t) => {
  const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "terminal-fence-agents"); await projectAgents(project, { "agent.md": definition("implement") }); const admitted = await admitDispatchCallInternal(projectRequest(project, await trust(project), { toolCallId: "terminal-fence" }), rootDir); const id = admitted.delegationIds![0]; await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id);
  const agent = { name: "implement", description: "implement", source: "project" as const, filePath: path.join(project, "agent.md"), systemPrompt: "Instructions" }; const ownerA: OwnerIdentity = { host: os.hostname(), pid: process.pid + 1, birth: "owner-a", parentSessionId, parentSessionPath: "/tmp/parent", argvProof: "a".repeat(64) }; const ownerB: OwnerIdentity = { ...ownerA, pid: process.pid + 2, birth: "owner-b" }; const childIdentity: ChildIdentity = { host: os.hostname(), pid: process.pid + 3, birth: "child-a", sessionPathHash: "b".repeat(32), argvProof: "c".repeat(64) }; let release!: () => void; const held = new Promise<void>((resolve) => { release = resolve; });
  const running = executeDelegationInternal(rootDir, admitted.dispatchCallId!, id, agent, { owner: ownerA, childIdentity, runAttempt: async (options: any) => { await options.onChildProcess?.({ pid: childIdentity.pid, identity: options.childSessionId }); await fs.writeFile(path.join(options.sessionDir, "session.jsonl"), `${JSON.stringify({ type: "session", version: 3, id: options.childSessionId, cwd: options.cwd, timestamp: new Date().toISOString() })}\n`); await held; return { agent: "implement", agentSource: "project", exitCode: 0, messages: [], toolResults: [], usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 1, turns: 1 }, requestedModel: "model", actualModel: "model", source: options.source, attempt: options.attempt, failureKind: "success", sessionId: options.childSessionId, cwdScope: "cwd:opaque" }; } });
  for (let i = 0; i < 100; i += 1) { if ((await readWal(rootDir, admitted.dispatchCallId!)).some((event) => event.type === "child_session_bound")) break; await new Promise((resolve) => setTimeout(resolve, 2)); }
  const boundEvent = (await readWal(rootDir, admitted.dispatchCallId!)).find((event) => event.type === "child_session_bound"); assert.ok(boundEvent?.data.childHost, JSON.stringify(boundEvent)); const transferred = await claimExecutionOwnerInternal(rootDir, admitted.dispatchCallId!, id, ownerB, { owner: ownerB, inspectOwner: async () => "dead", inspectChild: async () => "dead", childIdentity }); assert.equal(transferred.state, "transferred", JSON.stringify(transferred)); release(); const result = await running; assert.equal(result.state, "rejected"); assert.match(result.error ?? "", /fenced/);
});

