test("reattach executor consumes a live child result without spawning", async (t) => { const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "reattach-consume-agents"); await projectAgents(project, { "agent.md": definition("implement") }); const admitted = await admitDispatchCallInternal(projectRequest(project, await trust(project), { toolCallId: "reattach-consume" }), rootDir); const id = admitted.delegationIds![0]; await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id); const reservation = await reserveInitialInternal(rootDir, admitted.dispatchCallId!, id); assert.ok(reservation.state === "reserved" || reservation.state === "ready", JSON.stringify(reservation)); const beforeStart = await readDelegationInternal(rootDir, admitted.dispatchCallId!, id); assert.equal(beforeStart?.state, "initial_ready", JSON.stringify(beforeStart)); assert.ok((beforeStart as any)?.initialReservationId, JSON.stringify(beforeStart)); const started = await markSpawnStartedInternal(rootDir, admitted.dispatchCallId!, id, "initial"); assert.equal(started.state, "initial_running", JSON.stringify(started)); const binding = await bindChildSessionInternal(rootDir, admitted.dispatchCallId!, id, { owner: started.owner!, ownerGeneration: started.ownerGeneration!, fencingGeneration: started.fencingGeneration!, spawnId: started.spawnId! }, "live-child", undefined, 1234, { childIdentity: { host: os.hostname(), pid: 1234, birth: "child-live", sessionPathHash: "6".repeat(32), argvProof: "7".repeat(64) } }); assert.equal(binding.state, "bound", JSON.stringify(binding)); const beforeReattach = await readWal(rootDir, admitted.dispatchCallId!); assert.equal(beforeReattach.at(-1)?.type, "child_session_bound"); const result = await executeReattachedDelegationInternal(rootDir, admitted.dispatchCallId!, id, async (options) => { assert.equal(options.childSessionId, "live-child"); return { agent: "implement", agentSource: "project", exitCode: 0, messages: [], toolResults: [], usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 1 }, requestedModel: "model", actualModel: "model", source: "initial", attempt: 1, failureKind: "success", sessionId: options.childSessionId, cwdScope: "cwd:opaque" }; }, { inspectChild: async () => "live" }); assert.equal(result.state, "completed", result.error); assert.equal((await readWal(rootDir, admitted.dispatchCallId!)).filter((event) => event.type === "spawn_started").length, 1); });

test("ephemeral outcome remains readable when cleanup is pending", async (t) => { const rootDir = await root(); t.after(() => fs.rm(rootDir, { recursive: true, force: true })); const project = path.join(rootDir, "cleanup-killpoint-agents"); await projectAgents(project, { "agent.md": definition("implement") }); const admitted = await admitDispatchCallInternal(projectRequest(project, await trust(project), { toolCallId: "cleanup-killpoint", single: { agent: "implement", task: "private", persistent: false } }), rootDir); const id = admitted.delegationIds![0]; await resolveDelegationInternal(rootDir, admitted.dispatchCallId!, id); const agent = { name: "implement", description: "implement", source: "project" as const, filePath: path.join(project, "agent.md"), systemPrompt: "Instructions" }; const result = await executeDelegationInternal(rootDir, admitted.dispatchCallId!, id, agent, { cleanup: async () => { throw new Error("cleanup failed"); }, runAttempt: async (options: any) => { await options.onChildProcess?.({ pid: 1234, identity: options.childSessionId }); await fs.writeFile(path.join(options.sessionDir, "session.jsonl"), `${JSON.stringify({ type: "session", version: 3, id: options.childSessionId, cwd: options.cwd, timestamp: new Date().toISOString() })}\n`); return { agent: "implement", agentSource: "project", exitCode: 0, messages: [], toolResults: [], usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 1 }, requestedModel: "model", actualModel: "model", source: options.source, attempt: options.attempt, failureKind: "success", sessionId: options.childSessionId, cwdScope: "cwd:opaque" }; } }); const events = await readWal(rootDir, admitted.dispatchCallId!); assert.equal(result.state, "completed"); assert.deepEqual(events.slice(-1).map((event) => event.type), ["execution_outcome_captured"]); assert.equal(events.at(-1)?.data.cleanupRequired, true); assert.equal(events.at(-1)?.data.sessionRef, `v2:sessions/${id}`); assert.equal((await readDelegationInternal(rootDir, admitted.dispatchCallId!, id))?.cleanupPending, true); assert.equal((await readDelegationInternal(rootDir, admitted.dispatchCallId!, id))?.state, "returned"); });
